arguments.command:
sqlite3 data/logs.sqlite <<'EOF'
.mode column
.headers on
select stream, device, ab_arm, count(*), count(distinct session_id) sess, min(served_at), max(served_at), avg(propensity), min(candidate_count), max(candidate_count) from rec_serves group by 1,2,3;
select surface, count(*) from rec_serves group by 1;
select count(*), count(distinct serve_id) from rec_candidates;
select s.stream, count(distinct s.serve_id) from rec_serves s join rec_candidates c using(serve_id) group by 1;
select count(*), count(distinct serve_id||position), count(distinct click_id) from click_events;
select sum(slot_1 is null), sum(slot_5 is null) from rec_serves;
select filter_reason, count(*) from rec_candidates group by 1;
EOF

